 IEnumerator Run(){File.WriteAllText(Root+"/checks.txt","Necessary CPU/render/loading checks only. User performs visual acceptance.\n");yield return new WaitForSeconds(3);Logic();Prepare();var watch=System.Diagnostics.Stopwatch.StartNew();yield return Ready(256);Log("LOAD default="+watch.Elapsed.TotalMilliseconds+"ms");Check(plugin.Failure==null&&plugin.Renderer.Complete,"new shader loads and full view renders with SMAA");Check(plugin.Renderer.Parts.Values.All(p=>p.Texture.filterMode==FilterMode.Point&&p.Material.shader.isSupported),"pixel-footprint sampler uses unblurred source texels");
  float deadline=Time.realtimeSinceStartup+8;while(plugin.Analysis.Completed<plugin.Analysis.TotalPages&&Time.realtimeSinceStartup<deadline)yield return null;var first=plugin.Analysis.Get(1);var second=plugin.Analysis.Get(2);Check(first!=null&&second!=null&&first.Data.Skip(256*256).Take(256).SequenceEqual(second.Data.Take(256)),"new time spacing retains exact shared page boundary");tr.Play();int gaps=0;for(int i=0;i<180;i++){yield return null;Render();if(!plugin.Renderer.Complete||plugin.Renderer.LastMissing!=0)gaps++;}tr.Pause();Log("PLAY unready="+gaps+"/180 frames");Check(gaps==0,"short actual playback stays continuous across pages");
